contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= uint(0));

        c.SetMinSum(v); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted || c.MinSum() == v);
    }

    receive() external payable {}
}

